// The MHPCO rounds in its own favour: premiums up, payouts down.
const roundUpInMHPCOsFavour = (amount: number): number => Math.ceil(amount);

const quote = (step: Step): QuoteResult => {
  const basePremium = policyBasePremium(step.items);
  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
  const modifiedPremium = basePremium + firstInsuranceSurcharge;

  return {
    premium: roundUpInMHPCOsFavour(modifiedPremium + PROCESSING_FEE),
  };
};
